B.aoj=new A.hn("emergency","\uc751\uae09\uad6c\uc870\xb7\uc774\uc1a1 \uc870\uce58\uc5d0 \ub3d9\uc758\ud558\uba70, \uc7ac\uc555\uce58\ub8cc \uc811\uadfc\uc774 \uc9c0\uc5f0\ub420 \uc218 \uc788\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.")
B.rE=new A.hn("read","\ub3d9\uc758\uc11c \uc804\uccb4\ub97c \uc77d\uace0 \uc774\ud574\ud55c \ub4a4 \uc790\ubc1c\uc801\uc73c\ub85c \uc11c\uba85\ud569\ub2c8\ub2e4.")
