B.aoW=new A.rw("scuba","\uc2a4\ucfe0\ubc84 \uba74\ucc45","\uc2a4\ucfe0\ubc84\ub2e4\uc774\ube59 \ucc45\uc784 \uba74\ucc45 \ubc0f \uc704\ud5d8 \uc778\uc9c0\xb7\uc218\uc6a9 \ub3d9\uc758\uc11c","SCUBA DIVING LIABILITY RELEASE & ASSUMPTION OF RISK AGREEMENT","\ubcf8 \ub3d9\uc758\uc11c\ub294 APDI \uc2a4\ucfe0\ubc84\ub2e4\uc774\ube59 \uad50\uc721, \ud6c8\ub828 \ubc0f \uad00\ub828 \uc218\uc911\ud65c\ub3d9\uc5d0 \ucc38\uac00\ud558\ub294 \uc0ac\ub78c\uc774 \ud65c\ub3d9\uc758 \uc7a0\uc7ac\uc801 \uc704\ud5d8\uacfc \uc548\uc804\uc0c1 \uc758\ubb34\ub97c \ucda9\ubd84\ud788 \uc774\ud574\ud558\uace0, \uc790\ubc1c\uc801\uc73c\ub85c \ucc38\uac00\ud558\ub294\uc9c0 \ud655\uc778\ud558\uae30 \uc704\ud55c \ubb38\uc11c\uc785\ub2c8\ub2e4. \uc11c\uba85\ud558\uae30 \uc804\uc5d0 \ubaa8\ub4e0 \uc870\ud56d\uc744 \uc8fc\uc758 \uae4a\uac8c \uc77d\uace0 \ud544\uc694\ud55c \uc815\ubcf4\ub97c \uae30\uc7ac\ud558\uc5ec \uc8fc\uc2dc\uae30 \ubc14\ub78d\ub2c8\ub2e4.","\ubcf8 \ub3d9\uc758\uc11c\ub294 \ub2e4\uc774\ubc84 \uac74\uac15\uc9c4\uc220\uc11c, \uad50\uc721 \uc2e0\uccad\uc11c \ubc0f \uacfc\uc815\ubcc4 \uc548\uc804\uad50\uc721 \ud655\uc778\uc11c\ub97c \ub300\uccb4\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.",B.a1v,B.ZV)
B.a0U=s(["\ubcf8\uc778\uc740 \ud504\ub9ac\ub2e4\uc774\ube59\uc774 \uc678\ubd80 \ud638\ud761 \uae30\uccb4\uc758 \uacf5\uae09 \uc5c6\uc774 \ud638\ud761\uc744 \uc77c\uc2dc\uc801\uc73c\ub85c \uc815\uc9c0\ud55c \uc0c1\ud0dc\uc5d0\uc11c \uc218\ud589\ud558\ub294 \uc218\uc911\ud65c\ub3d9\uc774\uba70, \uc2a4\ucfe0\ubc84\ub2e4\uc774\ube59\uacfc\ub294 \ub2e4\ub978 \uace0\uc720\ud55c \uc704\ud5d8\uc774 \uc874\uc7ac\ud568\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \ub2e4\uc74c\uacfc \uac19\uc740 \uc704\ud5d8\uc744 \uc778\uc9c0\ud569\ub2c8\ub2e4."],t.s)
B.a_l=s(["\uc800\uc0b0\uc18c\uc99d(Hypoxia)\uc5d0 \ub530\ub978 \uc758\uc2dd \ubc0f \uc2e0\uccb4\uae30\ub2a5 \uc800\ud558","\uc800\uc0b0\uc18c\uc131 \uc758\uc2dd \uc18c\uc2e4(Blackout)\uacfc \uc6b4\ub3d9\uc870\uc808 \uc0c1\uc2e4(Loss of Motor Control)","\uacfc\ud638\ud761\uc73c\ub85c \uc778\ud55c \uc815\uc0c1\uc801\uc778 \ud638\ud761 \uc695\uad6c\uc758 \uc9c0\uc5f0 \ubc0f \uc704\ud5d8 \uc778\uc9c0 \ub2a5\ub825 \uac10\uc18c","\uadc0, \ubd80\ube44\ub3d9 \ubc0f \ud3d0\uc758 \uc555\ub825 \uc190\uc0c1","\uc218\uc911\uc5d0\uc11c\uc758 \ubc29\ud5a5\uac10\uac01 \uc0c1\uc2e4 \ubc0f \uc218\uba74 \ubcf5\uadc0\uc758 \uc5b4\ub824\uc6c0","\ud574\ub958, \ud30c\ub3c4, \uc218\uc628 \ubc0f \uc2dc\uc57c \ubcc0\ud654\uc5d0 \ub530\ub978 \uc704\ud5d8","\uc2e0\uccb4\uc801 \ud53c\ub85c, \uacf5\ud3ec, \uc2a4\ud2b8\ub808\uc2a4 \ubc0f \uac1c\uc778\uc758 \uac74\uac15 \uc0c1\ud0dc\uc5d0 \ub530\ub978 \uc704\ud5d8","\uc548\uc804\uc694\uc6d0\uc758 \uad6c\uc870 \ubc0f \uc751\uae09\uc758\ub8cc \uc870\uce58\uac00 \uc9c0\uc5f0\ub420 \uc218 \uc788\ub294 \uc704\ud5d8"],t.s)
B.aoy=new A.ee("\uc81c2\uc870. \ud504\ub9ac\ub2e4\uc774\ube59\uc758 \ud2b9\uc218 \uc704\ud5d8\uc5d0 \ub300\ud55c \uc778\uc9c0",B.a0U,B.a_l)
B.a1s=s(["\ubcf8\uc778\uc740 \ud504\ub9ac\ub2e4\uc774\ube59 \ucc38\uac00\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce60 \uc218 \uc788\ub294 \ubcf8\uc778\uc758 \uac74\uac15 \uc0c1\ud0dc\ub97c \uc815\ud655\ud558\uac8c \uace0\uc9c0\ud574\uc57c \ud568\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \ubcc4\ub3c4\uc758 \uac74\uac15\uc9c4\uc220\uc11c\uc5d0 \uc0ac\uc2e4\ub300\ub85c \uc751\ub2f5\ud558\uba70, \ud544\uc694\ud55c \uacbd\uc6b0 \uc758\ub8cc\uc804\ubb38\uac00\uc758 \ud3c9\uac00\ub97c \ubc1b\uaca0\uc2b5\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uad50\uc721 \uc911 \uc5b4\uc9c0\ub7ec\uc6c0, \ud1b5\uc99d, \ube44\uc815\uc0c1\uc801\uc778 \ud53c\ub85c \ub610\ub294 \uae30\ud0c0 \uc774\uc0c1 \uc99d\uc0c1\uc774 \ubc1c\uc0dd\ud558\ub294 \uacbd\uc6b0 \uc989\uc2dc \ub2f4\ub2f9 \uac15\uc0ac\uc5d0\uac8c \uc54c\ub9ac\uace0 \ud65c\ub3d9\uc744 \uc911\ub2e8\ud558\uaca0\uc2b5\ub2c8\ub2e4."],t.s)
B.aoH=new A.ee("\uc81c3\uc870. \uac74\uac15 \uc0c1\ud0dc \ubc0f \ucc38\uac00 \uc801\ud569\uc131",B.a1s,B.B)
B.YE=s(["\ubcf8\uc778\uc740 \ud504\ub9ac\ub2e4\uc774\ube59\uc5d0\uc11c \ubc84\ub514 \uc2dc\uc2a4\ud15c\uacfc \uc801\uc808\ud55c \uc548\uc804\uac10\ub3c5\uc774 \ud544\uc218\uc801\uc784\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \ub2e4\uc74c\uc758 \uc548\uc804\uc218\uce59\uc744 \uc900\uc218\ud558\uaca0\uc2b5\ub2c8\ub2e4."],t.s)
B.a1Y=s(["\ub2e8\ub3c5 \ud504\ub9ac\ub2e4\uc774\ube59\uc744 \uc2e4\uc2dc\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.","\uad50\uc721\uae30\uad00\uacfc \uac15\uc0ac\uac00 \uc9c0\uc815\ud55c \ubc84\ub514 \ubc0f \uc548\uc804\uad00\ub9ac \uccb4\uacc4\ub97c \uc900\uc218\ud569\ub2c8\ub2e4.","\uacfc\ud638\ud761\uacfc \ubb34\ub9ac\ud55c \uc228\ucc38\uae30 \uc2dc\ub3c4\ub97c \ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.","\uac1c\uc778\uc758 \ub2a5\ub825 \ubc0f \uad50\uc721 \ubc94\uc704\ub97c \ucd08\uacfc\ud558\ub294 \uc218\uc2ec\uc774\ub098 \uae30\ub85d\uc5d0 \ub3c4\uc804\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.","\uac15\uc0ac\uac00 \uc2b9\uc778\ud558\uc9c0 \uc54a\uc740 \ud6c8\ub828\uc744 \uc784\uc758\ub85c \uc218\ud589\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.","\ub2e4\uc774\ube59 \uc804\ud6c4 \ud544\uc694\ud55c \uc548\uc804 \ud655\uc778 \ubc0f \uc758\uc0ac\uc18c\ud1b5 \uc808\ucc28\ub97c \uc900\uc218\ud569\ub2c8\ub2e4.","\uc704\ud5d8\ud558\uac70\ub098 \ubd88\uc548\ud558\ub2e4\uace0 \ud310\ub2e8\ub418\ub294 \uacbd\uc6b0 \uc989\uc2dc \ud65c\ub3d9 \uc911\ub2e8\uc744 \uc694\uccad\ud569\ub2c8\ub2e4."],t.s)
B.aoM=new A.ee("\uc81c4\uc870. \ubc84\ub514 \uc2dc\uc2a4\ud15c \ubc0f \uc548\uc804\uad00\ub9ac",B.YE,B.a1Y)
B.a21=s(["\ubcf8\uc778\uc740 APDI \ud504\ub9ac\ub2e4\uc774\ube59 \uad50\uc721\uacfc\uc815\uc774 \uc774\ub860\uad50\uc721, \uc81c\ud55c\uc218\uc5ed \ub610\ub294 \uc218\uc601\uc7a5 \ud6c8\ub828, \uac1c\ubc29\uc218\uc5ed \ud6c8\ub828 \ubc0f \uacfc\uc815\ubcc4 \ud3c9\uac00\ud65c\ub3d9\uc744 \ud3ec\ud568\ud560 \uc218 \uc788\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uc815\ud574\uc9c4 \uad50\uc721\uacfc\uc815\uc5d0\uc11c \ub2f4\ub2f9 \uac15\uc0ac\uc758 \uc9c0\ub3c4\uc640 \uac10\ub3c5\uc5d0 \ub530\ub77c \ud65c\ub3d9\ud558\uaca0\uc2b5\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uae30\ub85d\uc774\ub098 \uac1c\uc778\uc801 \uc131\ucde8\ub97c \uc704\ud574 \uc548\uc804\uc218\uce59\uc744 \uc704\ubc18\ud558\uc9c0 \uc54a\uc73c\uba70, \uc801\uc808\ud55c \uc548\uc804\uac10\ub3c5 \uc5c6\uc774 \uc228\ucc38\uae30 \ud6c8\ub828\uc744 \uc2e4\uc2dc\ud558\uc9c0 \uc54a\uaca0\uc2b5\ub2c8\ub2e4."],t.s)
B.aoP=new A.ee("\uc81c5\uc870. \ud504\ub9ac\ub2e4\uc774\ube59 \uad50\uc721\ud65c\ub3d9\uc758 \uc774\ud574",B.a21,B.B)
B.a02=s(["\ubcf8\uc778\uc740 APDI\uac00 \ud504\ub9ac\ub2e4\uc774\ube59 \uad50\uc721 \uae30\uc900 \ubc0f \uad50\uc721\uccb4\uacc4\ub97c \uc81c\uacf5\ud558\ub294 \uc804\ubb38\ub2e8\uccb4\uc774\uba70, \uac1c\ubcc4 \uad50\uc721\uae30\uad00\uacfc \uac15\uc0ac\ub294 \ub3c5\ub9bd\uc801\uc73c\ub85c \ud65c\ub3d9\ud560 \uc218 \uc788\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ub2e4\ub9cc \uac01 \uae30\uad00 \ubc0f \uac15\uc0ac\uc758 \uad6c\uccb4\uc801\uc778 \ubc95\uc801 \ucc45\uc784\uc740 \uc2e4\uc81c \uc6b4\uc601\uad00\uacc4, \uad00\ub9ac\xb7\uac10\ub3c5\uad00\uacc4 \ubc0f \uad00\ub828 \ubc95\ub839\uc5d0 \ub530\ub77c \uacb0\uc815\ub428\uc744 \uc774\ud574\ud569\ub2c8\ub2e4."],t.s)
B.aoO=new A.ee("\uc81c6\uc870. \uad50\uc721\uae30\uad00\uacfc APDI\uc758 \uad00\uacc4",B.a02,B.B)
B.a1x=s(["\ubcf8\uc778\uc740 \ud504\ub9ac\ub2e4\uc774\ube59\uc758 \uc7a0\uc7ac\uc801\uc778 \uc704\ud5d8\uacfc \uc548\uc804\uc218\uce59\uc5d0 \ub300\ud55c \uc124\uba85\uc744 \ucda9\ubd84\ud788 \ub4e4\uc5c8\uc73c\uba70, \uc774\ub97c \uc774\ud574\ud55c \uc0c1\ud0dc\uc5d0\uc11c \uc790\ubc1c\uc801\uc73c\ub85c \uad50\uc721 \ubc0f \ud6c8\ub828\uc5d0 \ucc38\uac00\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uc801\uc808\ud55c \uad50\uc721\uacfc \uc548\uc804\uac10\ub3c5\uc774 \uc81c\uacf5\ub418\ub354\ub77c\ub3c4 \uc218\uc911\ud65c\ub3d9\uc5d0 \ub530\ub974\ub294 \ubaa8\ub4e0 \uc704\ud5d8\uc744 \uc644\uc804\ud788 \uc81c\uac70\ud560 \uc218 \uc5c6\uc74c\uc744 \uc778\uc815\ud569\ub2c8\ub2e4.","\ub610\ud55c \ubcf8\uc778\uc758 \uc548\uc804\uc218\uce59 \uc704\ubc18\uc774\ub098 \ubb34\ub9ac\ud55c \ud65c\ub3d9\uc774 \uc0ac\uace0 \uc704\ud5d8\uc744 \ub192\uc77c \uc218 \uc788\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4."],t.s)
B.aoT=new A.ee("\uc81c7\uc870. \uc790\ubc1c\uc801 \ucc38\uac00 \ubc0f \uc704\ud5d8 \uc218\uc6a9",B.a1x,B.B)
B.a_K=s(["\ubcf8\uc778\uc740 \ud504\ub9ac\ub2e4\uc774\ube59\uc758 \ubcf8\uc9c8\uc801\uc778 \uc704\ud5d8\uc744 \uc778\uc9c0\ud558\uace0 \uad00\uacc4 \ubc95\ub839\uc5d0\uc11c \ud5c8\uc6a9\ud558\ub294 \ubc94\uc704 \ub0b4\uc5d0\uc11c \uc774\ub7ec\ud55c \uc704\ud5d8\uc758 \ubc1c\uc0dd \uac00\ub2a5\uc131\uc744 \uc218\uc6a9\ud569\ub2c8\ub2e4.","\uadf8\ub7ec\ub098 \ubcf8 \ub3d9\uc758\uc11c\ub294 APDI, \uad50\uc721\uae30\uad00, \uac15\uc0ac \ubc0f \uad00\ub828\uc790\uc758 \uace0\uc758\xb7\uacfc\uc2e4\uc5d0 \ub530\ub978 \ubc95\uc801 \ucc45\uc784\uc744 \uc77c\uad04\uc801\uc73c\ub85c \uba74\uc81c\ud558\uac70\ub098 \ucc38\uac00\uc790\uc758 \uc815\ub2f9\ud55c \ubc95\uc801 \uad8c\ub9ac\ub97c \ud3ec\uae30\ud558\ub294 \uac83\uc73c\ub85c \ud574\uc11d\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.","\uc0ac\uace0 \ubc1c\uc0dd \uc2dc \ucc45\uc784\uc758 \uc720\ubb34 \ubc0f \ubc94\uc704\ub294 \uad6c\uccb4\uc801\uc778 \uc0ac\uace0 \uacbd\uc704\uc640 \uad00\uacc4 \ubc95\ub839\uc5d0 \ub530\ub77c \ud310\ub2e8\ub429\ub2c8\ub2e4."],t.s)
B.aoL=new A.ee("\uc81c8\uc870. \ucc45\uc784 \uba74\ucc45\uc758 \ubc94\uc704",B.a_K,B.B)
B.ZX=s(["\ubcf8\uc778\uc740 \ud504\ub9ac\ub2e4\uc774\ube59 \uc911 \uc758\uc2dd \uc18c\uc2e4 \ub610\ub294 \uae30\ud0c0 \uc751\uae09\uc0c1\ud669\uc774 \ubc1c\uc0dd\ud560 \uc218 \uc788\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\uc751\uae09\uc0c1\ud669 \ubc1c\uc0dd \uc2dc \uad50\uc721\uae30\uad00, \ub2f4\ub2f9 \uac15\uc0ac \ub610\ub294 \uc548\uc804\uc694\uc6d0\uc774 \uad6c\uc870 \uc694\uccad, \uc751\uae09\ucc98\uce58 \ubc0f \uc758\ub8cc\uae30\uad00 \uc774\uc1a1\uc744 \uc704\ud55c \uc870\uce58\ub97c \uc218\ud589\ud560 \uc218 \uc788\uc74c\uc744 \uc774\ud574\ud558\uace0 \uc774\uc5d0 \ub3d9\uc758\ud569\ub2c8\ub2e4."],t.s)
B.aoS=new A.ee("\uc81c9\uc870. \uc751\uae09\uc0c1\ud669 \ubc0f \uad6c\uc870 \ud611\uc870",B.ZX,B.B)
B.a1I=s(["\ubcf8\uc778\uc740 \ud504\ub9ac\ub2e4\uc774\ube59\uc758 \uace0\uc720\ud55c \uc704\ud5d8\uacfc \uc548\uc804\uc218\uce59\uc744 \ucda9\ubd84\ud788 \uc774\ud574\ud558\uc600\uc73c\uba70, \ubcf8 \ub3d9\uc758\uc11c\uc758 \ubaa8\ub4e0 \uc870\ud56d\uc744 \uc77d\uace0 \uc124\uba85\uc744 \uc694\uccad\ud560 \uae30\ud68c\ub97c \uac00\uc84c\uc2b5\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uc5b4\ub5a0\ud55c \uac15\uc694 \uc5c6\uc774 \uc790\ubc1c\uc801\uc73c\ub85c APDI \ud504\ub9ac\ub2e4\uc774\ube59 \uad50\uc721 \ubc0f \ud6c8\ub828\uc5d0 \ucc38\uac00\ud560 \uac83\uc744 \ud655\uc778\ud558\uace0 \uc11c\uba85\ud569\ub2c8\ub2e4."],t.s)
B.aoB=new A.ee("\uc81c10\uc870. \ucd5c\uc885 \ud655\uc778",B.a1I,B.B)
